const rawText = $input.item.json.text || "";
const webhookData = $("Webhook Trigger").item.json.body || {};

let parsed;

try {
  parsed = JSON.parse(rawText);
} catch (error) {
  throw new Error(
    "Invalid JSON received from LLM: " + error.message
  );
}

// Validate required AI fields
const category = parsed.category;
const urgencyScore = Number(parsed.urgency_score);
const summary = parsed.summary;

// Allow only categories defined in the LLM prompt
const allowedCategories = ["Emergency", "Routine", "Inquiry", "Needs_Review"];

if (!allowedCategories.includes(category)) {
  throw new Error("Invalid or missing category from LLM.");
}

// Validate urgency score
if (
  !Number.isInteger(urgencyScore) ||
  urgencyScore < 1 ||
  urgencyScore > 10
) {
  throw new Error("Invalid urgency score. Expected 1–10.");
}

// Validate summary
if (typeof summary !== "string" || !summary.trim()) {
  throw new Error("Missing or invalid patient summary.");
}

// Normalize patient information
return {
  Patient_Name: webhookData.Patient_Name || "Unknown",
  Phone: webhookData.Phone || "N/A",
  Email: webhookData.Email || "N/A",
  Age: webhookData.Age || "N/A",
  Symptoms: webhookData.Symptoms || "N/A",

  Category: category,
  Urgency_Score: urgencyScore,
  Summary: summary.trim()
};

const triage = $("Patient Alert Decision").first().json;

return [
  {
    json: {
      Patient_Name: triage.Patient_Name,
      Phone: triage.Phone,
      Email: triage.Email,
      Age: triage.Age,
      Symptoms: triage.Symptoms,
      Category: triage.Category,
      Urgency_Score: triage.Urgency_Score,
      Summary: triage.Summary
    }
  }
];
